-- Ids are generated by the database (a UUID as text) instead of by the application.
-- Existing 24-character ids stay as they are; the columns only get wider.
ALTER TABLE "sellers"
  ALTER COLUMN "id" TYPE VARCHAR(36),
  ALTER COLUMN "id" SET DEFAULT (gen_random_uuid())::text;

ALTER TABLE "listings"
  ALTER COLUMN "id" TYPE VARCHAR(36),
  ALTER COLUMN "seller" TYPE VARCHAR(36),
  ALTER COLUMN "id" SET DEFAULT (gen_random_uuid())::text;

ALTER TABLE "purchases"
  ALTER COLUMN "id" TYPE VARCHAR(36),
  ALTER COLUMN "seller" TYPE VARCHAR(36),
  ALTER COLUMN "listing" TYPE VARCHAR(36),
  ALTER COLUMN "id" SET DEFAULT (gen_random_uuid())::text;

ALTER TABLE "payouts"
  ALTER COLUMN "id" TYPE VARCHAR(36),
  ALTER COLUMN "seller" TYPE VARCHAR(36),
  ALTER COLUMN "id" SET DEFAULT (gen_random_uuid())::text;
